SELECT d.id, '3787ac53-7f9d-4da1-a73e-1a4b14739f55', 'artist', 'e005898c-4fcc-45da-b857-c6775e92fa52' FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id
